process SIMPLEAF_QUANT {
    tag "${meta.id ?: meta4.id}"
    label 'process_medium'

    conda "${moduleDir}/environment.yml"
    container "${ workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
?         'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/d0/d04c6d819d0712b766a7cf18aa39a15cced3ea4d79178c0811966d8a741b4db1/data'
:         'community.wave.seqera.io/library/piscem_simpleaf:8fd648760a75594c' }"

    input:
    //
    // Input reads are expected to come as: [ meta, [ pair1_read1, pair1_read2, pair2_read1, pair2_read2 ] ]
    // Input array for a sample is created in the same order reads appear in samplesheet as pairs from replicates are appended to array.
    //
    tuple val(meta), val(chemistry), path(reads)                        // chemistry and reads
    tuple val(meta2), path(index), path(txp2gene)                       // index and t2g mapping
    tuple val(meta3), val(cell_filter), val(number_cb), path(cb_list)   // cell filtering strategy
    val resolution                                                      // UMI resolution
    tuple val(meta4), path(map_dir)                                     // mapping results

    output:
    tuple val(meta), path("${prefix}/af_map")       , emit: map, optional: true // missing if map_dir is provided
    tuple val(meta), path("${prefix}/af_quant")     , emit: quant
    tuple val("${task.process}"), val('alevin-fry'), eval("alevin-fry --version | sed 's/alevin-fry //'"),                    topic: versions, emit: versions_alevin_fry
    tuple val("${task.process}"), val('piscem'),     eval("piscem --version | sed 's/piscem //'"),                            topic: versions, emit: versions_piscem
    tuple val("${task.process}"), val('simpleaf'),   eval("ALEVIN_FRY_HOME=. simpleaf --version | sed 's/simpleaf //'"),      topic: versions, emit: versions_simpleaf

    when:
    task.ext.when == null || task.ext.when

    script:
    def args      = task.ext.args ?: ''
    prefix    = task.ext.prefix ?: "${meta.id}"

    // The first required input is either a mapping result directory, or the reads and index files for mapping.
    mapping_args = mappingArgs(chemistry, reads, index, txp2gene, map_dir)

    // The second required input is a cell filtering strategy.
    cf_option = cellFilteringArgs(cell_filter, number_cb, cb_list)

    meta = map_dir ? meta4 : meta2 + meta3 + meta
    meta = meta + [ "filtered": cell_filter != "unfiltered-pl" ]

    // separate forward from reverse pairs
    """
    # export required var
    export ALEVIN_FRY_HOME=.

    # prep simpleaf
    simpleaf set-paths

    # run simpleaf quant
    simpleaf quant \\
        $mapping_args \\
        --resolution ${resolution} \\
        --output ${prefix} \\
        --threads ${task.cpus} \\
        --anndata-out \\
        ${cf_option} \\
        ${args}
    """

    stub:
    prefix    = task.ext.prefix ?: "${meta.id}"
    """
    export ALEVIN_FRY_HOME=.

    mkdir -p ${prefix}/af_map
    mkdir -p ${prefix}/af_quant/alevin

    touch ${prefix}/af_map/map.rad
    touch ${prefix}/af_map/unmapped_bc_count.bin
    touch ${prefix}/af_quant/alevin/quants_mat_rows.txt
    touch ${prefix}/af_quant/map.collated.rad
    touch ${prefix}/af_quant/permit_freq.bin
    """
}

// We have mutual exclusive options for permit list generation.
// 1. 'k' (knee), which is a flag for the knee method and any value provided will be ignored;
// 2. 'f' (forced-cells), which takes an integer indicating the exact number of cells to recover;
// 3. 'e' (expect-cells), which takes an integer indicating the expected number of cells to recover;
// 4. 'x' (explicit-pl), which takes a string indicating the path to a valid permit list;
// 5. 'u' (unfiltered-pl), which takes an empty string (if `chemistry` is defined as "10xv2" or "10xv3"), or a string indicating the path to a valid white list file.
// The difference between (4) and (5) is that (4) contains the exact permit list to filter the observed barcodes, while (5) will use the white list to generate a permit list via barcode correction.

// We have two ways to take these options. `-u` is implied by the presence of the input `whitelist` channel. The options can also be passed as arguments to ext.args. Therefore, we must check two things:
// 1. if there is at least one of the options in the args list, and
// 2. if none of the four options are in the args list, there must be a non-empty whitelist channel.

def cellFilteringArgs(cell_filter_method, number_cb, cb_list) {
    def pl_options = ["knee", "forced-cells", "explicit-pl", "expect-cells", "unfiltered-pl"]

    // try catch unintentional underscore in method name
    def method = cell_filter_method.replaceAll('_','-')

    def number = number_cb
    if (!method) {
        error "No cell filtering method was provided; cannot proceed."
    } else if (! method in pl_options) {
        error "Invalid cell filtering method, '${method}', was provided; cannot proceed. possible options are ${pl_options.join(',')}."
    }

    if (method == "unfiltered-pl") {
        return "--${method} ${cb_list}"
    } else if (method == "explicit-pl") {
        return "--${method} ${cb_list}"
    } else if (method == "knee") {
        return "--${method}"
    } else {
        if (!number) {
            error "Could not find the corresponding 'number' field for the cell filtering method '${method}'; please use the following format: [method:'${method}',number:3000]."
        }
        return "--${method} ${number}"
    }
}

def mappingArgs(chemistry, reads, index, txp2gene, map_dir) {
    if ( map_dir ) {
        if (reads) {
            error "Found both reads and map_dir. Please provide only one of the two."
        }
        return "--map-dir ${map_dir}"
    } else {
        if (!reads) {
            error "Missing read files; could not proceed."
        }
        if (!index) {
            error "Missing index files; could not proceed."
        }
        if (!chemistry) {
            error "Missing chemistry; could not proceed."
        }

        def (forward, reverse) = reads.collate(2).transpose()

        def t2g = txp2gene ? "--t2g-map ${txp2gene}" : ""
        def mapping_args = """${t2g} \\
        --chemistry ${chemistry} \\
        --index ${index} \\
        --reads1 ${forward.join( "," )} \\
        --reads2 ${reverse.join( "," )}"""
        return mapping_args
    }
}

nextflow_process {

    name "Test Process SIMPLEAF_QUANT"
    script "../main.nf"
    process "SIMPLEAF_QUANT"

    tag "modules"
    tag "modules_nfcore"
    tag "simpleaf"
    tag "simpleaf/quant"
    tag "simpleaf/index"


    //Requires SIMPLEAF_INDEX to run prior to quant
    setup {
        run("SIMPLEAF_INDEX") {
            script "../../index/main.nf"
            process {
                """
                genome_fasta = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                gtf = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                meta = [ 'id': 'human']

                input[0] = Channel.of([meta, genome_fasta, gtf])
                input[1] = Channel.of([[],[]])
                input[2] = Channel.of([[],[]])
                input[3] = Channel.of([[],[]])
                """
            }
        }
    }

    test("test_simpleaf_quant") {
        when {
            // config "./nextflow.config"
            process {
                """
                meta = [id:'test_10x', single_end:false, strandedness:'auto']
                files = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/5k_cmvpos_tcells/fastqs/gex_1/subsampled_5k_human_antiCMV_T_TBNK_connect_GEX_1_S1_L001_R1_001.fastq.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/5k_cmvpos_tcells/fastqs/gex_1/subsampled_5k_human_antiCMV_T_TBNK_connect_GEX_1_S1_L001_R2_001.fastq.gz', checkIfExists: true)
                ]
                input[0] = Channel.of([meta, '10xv3', files])
                input[1] = SIMPLEAF_INDEX.out.index.combine(SIMPLEAF_INDEX.out.t2g, by: 0)
                input[2] = [[],"knee",[],[]]
                input[3] = Channel.of('cr-like')
                input[4] = Channel.of([[],[]])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert file("${process.out.map.get(0).get(1)}/map.rad").exists() },
                { assert file("${process.out.map.get(0).get(1)}/map_info.json").exists() },
                { assert file("${process.out.map.get(0).get(1)}/unmapped_bc_count.bin").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/permit_map.bin").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/collate.json").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/generate_permit_list.json").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/quant.json").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/featureDump.txt").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/permit_freq.bin").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/unmapped_bc_count_collated.bin").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/alevin/quants_mat.mtx").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/alevin/quants_mat_cols.txt").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/alevin/quants_mat_rows.txt").exists() },
                { assert file("${process.out.quant.get(0).get(1)}/alevin/quants.h5ad").exists() },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith("versions")}).match() },
            )
        }

    }

    test("test_simpleaf_quant stub") {
        options "-stub-run"
            // config "./nextflow.config"

        when {
            process {
                """
                meta = [id:'test_10x', single_end:false, strandedness:'auto']
                files = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/5k_cmvpos_tcells/fastqs/gex_1/subsampled_5k_human_antiCMV_T_TBNK_connect_GEX_1_S1_L001_R1_001.fastq.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/5k_cmvpos_tcells/fastqs/gex_1/subsampled_5k_human_antiCMV_T_TBNK_connect_GEX_1_S1_L001_R2_001.fastq.gz', checkIfExists: true)
                ]
                input[0] = Channel.of([meta, '10xv3', files])
                input[1] = SIMPLEAF_INDEX.out.index.combine(SIMPLEAF_INDEX.out.t2g, by: 0)
                input[2] = [[],"knee",[],[]]
                input[3] = Channel.of('cr-like')
                input[4] = Channel.of([[],[]])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}
